import { readFileSync, writeFileSync } from "node:fs";
import { packageInfo } from "./package-info.mjs";
const { manifest, filename } = packageInfo();
const contents = [
  "<!-- Generated by npm run docs:versions; do not edit. -->",
  "# Build information",
  "",
  "Source version: **v" + manifest.version + "**.",
  "",
  "`npm run package` builds and verifies `../" +
    filename +
    "` from `package.json`.",
  "This does not publish a release or install the extension.",
  "",
].join("\n");
const path = "docs/build-info.md";
if (process.argv.includes("--check")) {
  if (readFileSync(path, "utf8") !== contents)
    throw Error("Build information is stale. Run npm run docs:versions.");
} else writeFileSync(path, contents);
